package br.com.conectatea.security;
import static org.assertj.core.api.Assertions.assertThat;
import br.com.conectatea.config.AppProperties; import br.com.conectatea.usuario.domain.*; import java.time.Duration; import org.junit.jupiter.api.Test; import org.springframework.test.util.ReflectionTestUtils;
class JwtServiceTest { @Test void roundTripKeepsIdentityAndIssuedAt(){var props=new AppProperties(new AppProperties.Jwt("0123456789012345678901234567890123456789",Duration.ofHours(1)),new AppProperties.Cors("http://localhost:5173"),new AppProperties.Cookie(false,"Lax"));var service=new JwtService(props);var user=new Usuario("Maria","MARIA@example.com","hash",null,null,TipoUsuario.RESPONSAVEL);ReflectionTestUtils.setField(user,"id",42L);var token=service.issue(user);var parsed=service.parse(token);assertThat(parsed.id()).isEqualTo(42L);assertThat(parsed.email()).isEqualTo("maria@example.com");assertThat(parsed.tipo()).isEqualTo(TipoUsuario.RESPONSAVEL);assertThat(parsed.issuedAt()).isNotNull();}
}
